export const getUploadMediaUrl = () => {




  return `/api/admin/media`
}

/**
 * Stores the request body and returns its URL for use in GameConfig.media. Send the file with its own Content-Type: PNG, JPEG, GIF, WebP or SVG images, MP3, WAV, OGG, M4A or AAC audio, MP4 or WebM video (100 MB max).
 */
export const uploadMedia = async (uploadMediaBody: Blob, options?: Parameters<typeof customFetch>[1]): Promise<MediaUpload> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<MediaUpload>(getUploadMediaUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/octet-stream', ...getHeaders(options?.headers) },
    body: uploadMediaBody
  }
);}





